import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.DJVIMu25.js";const p=JSON.parse('{"title":"快速开始","description":"","frontmatter":{"title":"快速开始"},"headers":[],"relativePath":"zh_Hans/guides/getting-started.md","filePath":"zh_Hans/guides/getting-started.md","lastUpdated":1786543805000}'),s={name:"zh_Hans/guides/getting-started.md"};function i(d,t,l,n,c,g){return e(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>一个为 <strong>Spigot / Paper 1.21 – 1.21.6</strong> 打造的全 GUI 我的世界小游戏大厅插件。15 款游戏全部内置在主 jar 中，无需额外模块加载，丢进 <code>plugins/</code> 即开箱即玩。</p><div class="tip custom-block"><p class="custom-block-title">主类信息</p><p>主类：<code>me.nikl.gamebox.GameBox</code> · 版本：<code>1.0</code> · 构建：Maven shade（依赖重定位至 <code>me.nikl.gamebox.common.*</code>）</p></div><h2 id="灵感来源与致谢" tabindex="-1">灵感来源与致谢 <a class="header-anchor" href="#灵感来源与致谢" aria-label="Permalink to &quot;灵感来源与致谢&quot;">​</a></h2><p>JoyMart 的设计与实现由作者<strong>完全独立自研</strong>，代码、游戏逻辑、GUI 交互、数据存储均为本仓库原创实现。</p><p>在产品形态、玩法思路与用户体验方面，本项目参考并致敬了以下两款优秀的 Spigot 社区作品：</p><ul><li><a href="https://www.spigotmc.org/resources/jukebox-music-plugin.40580/" target="_blank" rel="noreferrer">JukeBox - Music Plugin</a> — 提供了&quot;音乐播放器 + NBS 乐谱&quot;的灵感来源，本项目的内置 <code>MusicPlayer</code>（NBS 乐谱解析 + 音符盒序列播放）正是在此启发下重新自研实现。</li><li><a href="https://www.spigotmc.org/resources/gamebox-inventory-games-collection.37273/" target="_blank" rel="noreferrer">GameBox - Inventory Games Collection</a> — 提供了&quot;通过箱子 GUI 聚合多款小游戏&quot;的整体产品形态灵感，本项目的 15 款游戏、代币系统、高分榜、双人邀请、AI 对战等内容均为独立重写，未引用其代码。</li></ul><div class="tip custom-block"><p class="custom-block-title">致谢</p><p>上述链接为 SpigotMC 资源页，可点击跳转查看原作品。感谢原作者们为社区带来的优秀作品。</p></div><h2 id="特性一览" tabindex="-1">特性一览 <a class="header-anchor" href="#特性一览" aria-label="Permalink to &quot;特性一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>说明</th></tr></thead><tbody><tr><td><strong>纯 GUI 操作</strong></td><td>通过箱子界面选择游戏，玩家无需记忆任何指令。</td></tr><tr><td><strong>15 款内置游戏</strong></td><td>单人：2048、扫雷、打地鼠、宝石迷阵、彩票、抽奖机、迷宫、贪吃蛇、小恐龙跑酷；双人：战舰、四子棋、井字棋、石头剪刀布、国际象棋；多人：大富翁（2–3 人，含 AI 与下注模式）。</td></tr><tr><td><strong>代币系统</strong></td><td>自带 JoyMart 代币，可选挂钩 Vault 经济（金币）。</td></tr><tr><td><strong>高分榜</strong></td><td>自动记录每款游戏的最高分，支持跨服 MySQL 同步。</td></tr><tr><td><strong>双人对战 + AI</strong></td><td>双人游戏支持邀请好友或直接对战 AI（无需等待对手）。</td></tr><tr><td><strong>可配置奖项池</strong></td><td>彩票 / 抽奖机共享奖项池，管理员可在游戏内 GUI 增删奖项、调整权重与代币/金币/命令奖励。</td></tr><tr><td><strong>大厅模式</strong></td><td>在指定世界自动发放快捷物品，点击直接打开主菜单。</td></tr><tr><td><strong>双存储</strong></td><td>YAML 文件（默认）或 MySQL（HikariCP 连接池，支持 BungeeCord 跨服）。</td></tr><tr><td><strong>自定义事件</strong></td><td>进入 / 离开 JoyMart 时可执行配置的命令。</td></tr><tr><td><strong>公开 API</strong></td><td>通过 <code>GameBoxAPI</code> 或 Bukkit ServicesManager 供其他插件调用。</td></tr><tr><td><strong>挂钩支持</strong></td><td>PlaceholderAPI、bStats、CalendarEvents（自动检测）。</td></tr><tr><td><strong>多语言</strong></td><td>内置英 / 中 / 德 / 西 四种语言。</td></tr><tr><td><strong>Scoreboard</strong></td><td>游戏进行中在侧边栏显示当前游戏、分数、最高分、代币。</td></tr></tbody></table><h2 id="安装与构建" tabindex="-1">安装与构建 <a class="header-anchor" href="#安装与构建" aria-label="Permalink to &quot;安装与构建&quot;">​</a></h2><h3 id="方式-a-自行构建-推荐" tabindex="-1">方式 A：自行构建（推荐） <a class="header-anchor" href="#方式-a-自行构建-推荐" aria-label="Permalink to &quot;方式 A：自行构建（推荐）&quot;">​</a></h3><p>需要 <strong>JDK 21+</strong> 和 <strong>Maven 3.6+</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/myzer121/JoyMart.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> JoyMart</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span></span></code></pre></div><p>构建产物：<code>target/JoyMart-1.0.jar</code></p><h3 id="方式-b-使用预编译-jar" tabindex="-1">方式 B：使用预编译 jar <a class="header-anchor" href="#方式-b-使用预编译-jar" aria-label="Permalink to &quot;方式 B：使用预编译 jar&quot;">​</a></h3><p>如果你拿到了发布版的 <code>JoyMart-1.0.jar</code>，直接放到服务器的 <code>plugins/</code> 目录即可。</p><h3 id="服务器要求" tabindex="-1">服务器要求 <a class="header-anchor" href="#服务器要求" aria-label="Permalink to &quot;服务器要求&quot;">​</a></h3><ul><li><strong>Paper / Spigot 1.21 – 1.21.6</strong>（Paper 推荐）</li><li><strong>Java 21+</strong></li><li>可选：<a href="https://www.spigotmc.org/resources/vault.34315/" target="_blank" rel="noreferrer">Vault</a> + 任意经济插件</li><li>可选：<a href="https://github.com/HelpChat/PlaceholderAPI" target="_blank" rel="noreferrer">PlaceholderAPI</a></li><li>可选：<a href="https://github.com/niklasstern/CalendarEvents" target="_blank" rel="noreferrer">CalendarEvents</a>（节日彩蛋）</li></ul><h2 id="首次使用" tabindex="-1">首次使用 <a class="header-anchor" href="#首次使用" aria-label="Permalink to &quot;首次使用&quot;">​</a></h2><ol><li>把 <code>JoyMart-1.0.jar</code> 放进 <code>plugins/</code>，启动一次服务器，让插件生成默认配置。</li><li>编辑 <code>plugins/JoyMart/config.yml</code> 按需调整（经济、大厅、邀请、音效、Scoreboard 等）。</li><li>编辑 <code>plugins/JoyMart/games.yml</code> 开关每款游戏、配置子命令。</li><li>编辑 <code>plugins/JoyMart/tokenShop.yml</code> 增删商店商品。</li><li>执行 <code>/gba reload</code> 重载，或重启服务器。</li><li>玩家执行 <code>/gamebox</code> 即可打开主菜单。</li></ol><div class="tip custom-block"><p class="custom-block-title">下一步</p><p>配置完成后，可前往 <a href="./commands">命令与权限</a> 了解玩家与管理命令，或查看 <a href="./configuration">配置文件说明</a> 深入了解各项配置，也可以直接浏览 <a href="./games">游戏模式</a> 开始游玩。</p></div>`,22)])])}const u=a(s,[["render",i]]);export{p as __pageData,u as default};
